class GymMember {protected String id;protected int fee;private int sessions;public GymMember(String i,int f){if(i==null||i.trim().length()<4)throw new IllegalArgumentException("Invalid ID");if(f<=0)throw new IllegalArgumentException("Fee must be positive");id=i;fee=f;}public void attendSession(){sessions++;}public int getSessionsAttended(){return sessions;}public void displayInfo(){System.out.print("Standard | Sessions: "+sessions);}}
class PremiumMember extends GymMember {private String trainer;public PremiumMember(String i,int f,String t){super(i,f);trainer=t;}public String getTrainerName(){return trainer;}@Override public void displayInfo(){System.out.print("Premium | Trainer: "+trainer+" | Sessions: "+getSessionsAttended());}}
public class MonthlyAttendanceAnnouncerMain {
 public static String batchPrint(GymMember[] ms){StringBuilder b=new StringBuilder();for(GymMember m:ms){if(b.length()>0)b.append(" | ");if(m instanceof PremiumMember){PremiumMember p=(PremiumMember)m;b.append("Premium | Trainer: ").append(p.getTrainerName()).append(" | Sessions: ").append(p.getSessionsAttended()).append(" [Trainer via downcast: ").append(p.getTrainerName()).append("]");}else b.append("Standard | Sessions: ").append(m.getSessionsAttended());}return b.toString();}
 public static void main(String[] a){System.out.println(batchPrint(new GymMember[]{new GymMember("MEM6",1000),new PremiumMember("MEM7",2000,"Coach Riya")}));}
}
